mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.member member,
  ttokssaemdb.checkvocaplan vocatest

  AND member.memberid = vocatest.memberid

    AND vocatest.memodate = #{memodate}


    AND (
      member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT member.memberid, member.membername, vocatest.id, vocatest.memodate, vocatest.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocatest.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocatest.vocano, vocatest.targetcount, vocatest.lastyn, vocatest.examflag FROM ttokssaemdb.member member, ttokssaemdb.checkvocaplan vocatest
AND member.memberid = vocatest.memberid
AND vocatest.memodate = #{memodate}
AND ( member.membername LIKE #{likeQuery} )
vocatest.id vocatest.vocalevel vocatest.vocalevel vocatest.vocano vocatest.memodate vocatest.lastyn member.membername DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
